python3 -c "
import pathlib
p = pathlib.Path('src/codegen/context.rs')
t = p.read_text()
old = '''        let crate::ir::Immediate::RuntimeCall(target) = inst.immediate.as_ref()? else {
            return None;
        };
        Some((target.php_name(), line, inst.operands.clone()))'''
new = '''        let crate::ir::Immediate::RuntimeCall(target) = inst.immediate.as_ref()? else {
            return None;
        };
        // Only a plain typed builtin names itself the way php does; the array/cell helpers are
        // internal shapes php has never heard of, and a profiled call wraps one of the same.
        let name = match target {
            crate::ir::runtime_call::RuntimeCallTarget::Function(target)
            | crate::ir::runtime_call::RuntimeCallTarget::ProfiledFunction { target, .. } => {
                target.php_name()
            }
            _ => return None,
        };
        Some((name, line, inst.operands.clone()))'''
assert t.count(old) == 1
p.write_text(t.replace(old, new, 1))
print('patched')
